import json
from pathlib import Path

class StockStore:
    def __init__(self, path):
        self.path = Path(path)

    def load(self):
        if not self.path.exists():
            return {}
        return json.loads(self.path.read_text(encoding="utf-8"))

    def save(self, stock):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps(stock, sort_keys=True) + "\n", encoding="utf-8")

    def add(self, sku, quantity):
        stock = self.load()
        stock[sku] = stock.get(sku, 0) + quantity
        self.save(stock)
        return stock[sku]
